def findJudge(n: int, trust: list[list[int]]) -> int:
    net_trust = [0] * (n + 1)
    for a, b in trust:
        net_trust[a] -= 1
        net_trust[b] += 1
    for i in range(1, n + 1):
        if net_trust[i] == n - 1:
            return i
    return -1

